cdd1dea","description":"Isaac Newton","correct_answer":false},{"id":"01a2190a-af2f-7761-9904-f8c114d55ce8","description":"Galileu Galilei","correct_answer":false}]},{"id":"01a2190a-af2f-7429-b68a-3901ac09d140","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual termo se refere a objetos ou retas que est\u00e3o lado a lado e nunca se cruzam?","difficulty":1,"explanation":"As retas paralelas mant\u00eam a mesma dist\u00e2ncia entre si; as retas perpendiculares se encontram em um \u00e2ngulo reto, enquanto as retas convergentes se aproximam uma da outra.","alternatives":[{"id":"01a2190a-af2f-7048-bdd4-6e2a08b31b82","description":"Paralelas","correct_answer":true},{"id":"01a2190a-af2f-7947-b447-ef42972c6c3d","description":"Perpendiculares","correct_answer":false},{"id":"01a2190a-af2f-75fd-a840-95edfa209bd2","description":"Diagonal","correct_answer":false},{"id":"01a2190a-af2f-7ba9-acdd-f41006520f44","description":"Convergente","correct_answer":false}]},{"id":"01a2190a-af2f-79c8-bd6c-6622d058c894","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"As iguanas marinhas, os crocodilos de \u00e1gua salgada, as cobras marinhas e as tartarugas marinhas pertencem a qual classe de animais?","difficulty":1,"explanation":"Os r\u00e9pteis s\u00e3o vertebrados que respiram ar e possuem escamas. As tartarugas-marinhas precisam subir \u00e0 superf\u00edcie para respirar, enquanto as iguanas marinhas conseguem prender a respira\u00e7\u00e3o debaixo d\u2019\u00e1gua.","alternatives":[{"id":"01a2190a-af2f-7ff8-85ce-2f0be3722cc0","description":"R\u00e9pteis","correct_answer":true},{"id":"01a2190a-af2f-78e6-8cfe-3b46273f0376","description":"Mam\u00edferos","correct_answer":false},{"id":"01a2190a-af2f-7dca-9542-39e0b9189bf9","description":"Anf\u00edbios","correct_answer":false},{"id":"01a2190a-af2f-7f32-a0fb-eb857436ce14","description":"Peixes","correct_answer":false}]},{"id":"01a2190a-af2f-7024-a76a-3cebad7ad9bb","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Como voc\u00ea chamaria um filhote de coruja?","difficulty":1,"explanation":"Um \u201cowlet\u201d \u00e9 um filhote de coruja; a termina\u00e7\u00e3o -let geralmente indica algo pequeno ou jovem, como em \u201cpiglet\u201d (leit\u00e3o).","alternatives":[{"id":"01a2190a-af2f-76a2-81e3-7eb9c40762d0","description":"Um filhote de coruja","correct_answer":true},{"id":"01a2190a-af2f-7723-95aa-b3e71b9af379","description":"Uma lagarta","correct_answer":false},{"id":"01a2190a-af2f-7749-9264-30f377f5cb36","description":"Um codling","correct_answer":false},{"id":"01a2190a-af2f-785f-9fbf-fe379ecb986c","description":"Um potro","correct_answer":false}]},{"id":"01a2190a-af2f-730f-b465-4796b19977f3","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Como se chama uma borboleta jovem?","difficulty":1,"explanation":"A lagarta \u00e9 o est\u00e1gio larval da borboleta; depois de crescer, ela forma uma cris\u00e1lida e, mais tarde, emerge como adulto.","alternatives":[{"id":"01a2190a-af2f-7b2d-aec6-0329b5e00f31","description":"Uma lagarta","correct_answer":true},{"id":"01a2190a-af2f-74a7-9eb4-4ce23ff2553c","description":"Um gatinho","correct_answer":false},{"id":"01a2190a-af2f-74cc-811d-ded8ae7d90ac","description":"Um pintinho","correct_answer":false},{"id":"01a2190a-af2f-7bba-b6e5-0f5c7f18364e","description":"Uma aranha beb\u00ea","correct_answer":false}]},{"id":"01a2190a-af2f-73ae-a022-2d8575148b22","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"De que tipo de \u00e1rvore v\u00eam tanto as t\u00e2maras quanto os cocos?","difficulty":1,"explanation":"As tamareiras e os coqueiros s\u00e3o esp\u00e9cies diferentes da fam\u00edlia das palmeiras, que tamb\u00e9m inclui muitas plantas ornamentais e produtoras de \u00f3leo.","alternatives":[{"id":"01a2190a-af2f-70a9-a9bd-197f59ce6c1f","description":"Palmeira","correct_answer":true},{"id":"01a2190a-af2f-7431-96e4-926841f48109","description":"Bordo","correct_answer":false},{"id":"01a2190a-af2f-7846-9d05-3b9883409083","description":"B\u00e9tula","correct_answer":false},{"id":"01a2190a-af2f-76d5-bf26-2e1a56252749","description":"Abeto","correct_answer":false}]},{"id":"01a2190a-af2f-7395-a1fc-127a1ceb7a77","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual fruta apresenta seus aqu\u00eanios (ov\u00e1rios com sementes) na parte externa?","difficulty":1,"explanation":"A polpa vermelha \u00e9 um recept\u00e1culo floral aumentado; cada aqu\u00eanio \u00e9 um pequeno fruto seco que cont\u00e9m uma semente.","alternatives":[{"id":"01a2190a-af2f-7a4d-ad54-6a1abf6d5be1","description":"Morango","correct_answer":true},{"id":"01a2190a-af2f-7108-a2b9-4af005cf6961","description":"Ma\u00e7\u00e3","correct_answer":false},{"id":"01a2190a-af2f-78ca-b159-5d318ae05bbb","description":"Uva","correct_answer":false},{"id":"01a2190a-af2f-78b5-be12-25b499d4e441","description":"Banana","correct_answer":false}]},{"id":"01a2190a-af2f-713c-81aa-ebfadf3c70b5","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 a palavra para designar um grupo de le\u00f5es?","difficulty":1,"explanation":"Uma alcateia geralmente inclui f\u00eameas aparentadas, seus filhotes e um ou mais machos adultos.","alternatives":[{"id":"01a2190a-af2f-756d-949d-0fdaebf0d471","description":"Uma alcateia","correct_answer":true},{"id":"01a2190a-af2f-7422-9800-319bca6fe49c","description":"Um rebanho","correct_answer":false},{"id":"01a2190a-af2f-757c-9cf0-3fb38b2c19f9","description":"Um clowder","correct_answer":false},{"id":"01a2190a-af2f-7c06-811d-84431765be1a","description":"Uma shrewdness","correct_answer":false}]},{"id":"01a2190a-af2f-78eb-85b3-e6e300d6742c","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 o maior planeta do sistema solar?","difficulty":1,"explanation":"J\u00fapiter \u00e9 um gigante gasoso, e sua Grande Mancha Vermelha \u00e9 maior do que a Terra.","alternatives":[{"id":"01a2190a-af2f-7069-a2dd-0ee715c64ce8","description":"J\u00fapiter","correct_answer":true},{"id":"01a2190a-af2f-7563-bca8-5ea8705e2d32","description":"Saturno","correct_answer":false},{"id":"01a2190a-af2f-7ab2-9171-7fc75365dabc","description":"Terra","correct_answer":false},{"id":"01a2190a-af2f-7d9d-a01b-fa69e31d0891","description":"Urano","correct_answer":false}]},{"id":"01a2190a-af2f-7451-8ad3-ed2ef7ef456e","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 o processo pelo qual tanto o leite quanto o sangue podem se tornar semiss\u00f3lidos?","difficulty":1,"explanation":"A coagula\u00e7\u00e3o ocorre quando a fibrina forma uma rede no sangue; no leite, as prote\u00ednas se aglomeram formando coalhada, como na fabrica\u00e7\u00e3o de queijo.","alternatives":[{"id":"01a2190a-af2f-7519-9399-9628541b0b3d","description":"Coagula\u00e7\u00e3o","correct_answer":true},{"id":"01a2190a-af2f-7355-b41b-cb58835afcb0","description":"Pasteuriza\u00e7\u00e3o","correct_answer":false},{"id":"01a2190a-af2f-7e44-afe0-762081729c5d","description":"Filtra\u00e7\u00e3o","correct_answer":false},{"id":"01a2190a-af2f-7e36-860e-3c95d5224a46","description":"Destila\u00e7\u00e3o","correct_answer":false}]},{"id":"01a2190a-af2f-7e6d-bf4d-57a41897068c","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 o termo para um mineral que cont\u00e9m metal?","difficulty":1,"explanation":"Um min\u00e9rio cont\u00e9m material valioso o suficiente para que a extra\u00e7\u00e3o valha a pena; nem toda rocha que cont\u00e9m metal se enquadra nessa defini\u00e7\u00e3o.","alternatives":[{"id":"01a2190a-af2f-70e9-a82b-36a325827ed0","description":"Min\u00e9rio","correct_answer":true},{"id":"01a2190a-af2f-7648-bb0f-09bca5d42396","description":"Turfa","correct_answer":false},{"id":"01a2190a-af2f-71d4-af89-6f2d5724ebf7","description":"Pedra","correct_answer":false},{"id":"01a2190a-af2f-7faf-9d57-462f1b6cb8c4","description":"Cimento","correct_answer":false}]},{"id":"01a2190a-af2f-79ec-b2e3-91410f6a535c","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Como se chama uma f\u00eamea de veado?","difficulty":1,"explanation":"Uma \u201cdoe\u201d tamb\u00e9m \u00e9 uma coelha adulta; um veado macho adulto \u00e9 chamado de \u201cbuck\u201d.","alternatives":[{"id":"01a2190a-af2f-724a-bfff-c1214805e8a4","description":"Uma cor\u00e7a","correct_answer":true},{"id":"01a2190a-af2f-72e4-a1e6-227d4ed1fd14","description":"Um cercado","correct_answer":false},{"id":"01a2190a-af2f-7ba0-a07f-ad9d7ebc126d","description":"Uma \u00e9gua","correct_answer":false},{"id":"01a2190a-af2f-7a4c-9792-2c9456af3ebd","description":"Uma cabra","correct_answer":false}]},{"id":"01a2190a-af2f-73c7-af12-666a16610e6c","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Que tipo de organismo \u00e9 uma sanguessuga?","difficulty":1,"explanation":"A sanguessuga \u00e9 um parasita, pois se alimenta de um hospedeiro; muitas esp\u00e9cies usam ventosas para se fixar nos animais.","alternatives":[{"id":"01a2190a-af2f-775a-a195-7881bca6ed94","description":"Parasita","correct_answer":true},{"id":"01a2190a-af2f-7a0a-918c-c8661efc3335","description":"Herb\u00edvoro","correct_answer":false},{"id":"01a2190a-af2f-7d74-a991-248f3a40400f","description":"On\u00edvoro","correct_answer":false},{"id":"01a2190a-af2f-75f2-959f-76bbcfbbc74d","description":"Decompositor","correct_answer":false}]},{"id":"01a2190a-af2f-7763-a8b5-7531c7ad1575","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 a maior cobra?","difficulty":1,"explanation":"As anacondas s\u00e3o geralmente consideradas as maiores cobras em termos de peso, embora as p\u00edtons reticuladas possam atingir comprimentos maiores.","alternatives":[{"id":"01a2190a-af2f-7471-b126-334e65e3781d","description":"Anaconda","correct_answer":true},{"id":"01a2190a-af2f-7744-9ab1-42ce7a8fb4c6","description":"Mamba-preta","correct_answer":false},{"id":"01a2190a-af2f-7c5a-a830-4646653671a0","description":"Cascavel","correct_answer":false},{"id":"01a2190a-af2f-79ee-bf42-ed35fb0429fc","description":"Cobra-real","correct_answer":false}]},{"id":"01a2190a-af2f-777e-bc17-4d9b5e424d76","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Que tipo de figura pode ser obtusa ou is\u00f3sceles?","difficulty":1,"explanation":"A soma dos \u00e2ngulos de um tri\u00e2ngulo \u00e9 de 180 graus; \u201cobtusa\u201d descreve um \u00e2ngulo maior que 90 graus, enquanto \u201cis\u00f3sceles\u201d significa que dois lados s\u00e3o iguais.","alternatives":[{"id":"01a2190a-af2f-7acf-acfd-11bef137100d","description":"Um tri\u00e2ngulo","correct_answer":true},{"id":"01a2190a-af2f-7e65-a9cd-d915a2ce7757","description":"Um quadrado","correct_answer":false},{"id":"01a2190a-af2f-75b3-a610-5073fa3a4492","description":"Um c\u00edrculo","correct_answer":false},{"id":"01a2190a-af2f-718c-9a63-e6eac9adb999","description":"Um ret\u00e2ngulo","correct_answer":false}]},{"id":"01a2190a-af2f-7fd0-9993-1aa9d89adc55","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"O que \u00e9 feito de cascalho, areia, cimento e \u00e1gua?","difficulty":1,"explanation":"O concreto endurece \u00e0 medida que o cimento reage com a \u00e1gua, unindo a areia e o cascalho.","alternatives":[{"id":"01a2190a-af2f-780e-bfa5-ea4391cf0333","description":"Concreto","correct_answer":true},{"id":"01a2190a-af2f-735b-bd10-7df611ebe5f1","description":"Porcelana","correct_answer":false},{"id":"01a2190a-af2f-76ba-b312-f948d168c18a","description":"Gesso","correct_answer":false},{"id":"01a2190a-af2f-7b57-85cb-2f2fe2c6c19b","description":"Giz","correct_answer":false}]},{"id":"01a2190a-af2f-7f4f-a6a3-c1d8e42bb9eb","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Quantos membros um polvo tem?","difficulty":1,"explanation":"Um polvo tem 8 membros, geralmente chamados de bra\u00e7os. Eles n\u00e3o t\u00eam ossos, o que ajuda o animal a se espremer por espa\u00e7os estreitos.","alternatives":[{"id":"01a2190a-af2f-7455-b448-7a33003222e1","description":"8","correct_answer":true},{"id":"01a2190a-af2f-75bb-97b1-673321c7669a","description":"6","correct_answer":false},{"id":"01a2190a-af2f-7931-b59e-f32c6030275d","description":"10","correct_answer":false},{"id":"01a2190a-af2f-7cc1-ab8c-bc6527feaab7","description":"14","correct_answer":false}]},{"id":"01a2190a-af2f-7fcb-8fb1-e7bfc6a6f696","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"A qu\u00edmica da vida gira em torno de qual elemento?","difficulty":1,"explanation":"O carbono possui quatro el\u00e9trons de val\u00eancia, o que lhe permite formar liga\u00e7\u00f5es est\u00e1veis com muitos elementos e construir as cadeias e os an\u00e9is encontrados nas biomol\u00e9culas.","alternatives":[{"id":"01a2190a-af2f-7c6e-82db-c66d3e0b59bc","description":"Carbono","correct_answer":true},{"id":"01a2190a-af2f-7d3d-9932-75761c25815c","description":"F\u00f3sforo","correct_answer":false},{"id":"01a2190a-af2f-7d65-b907-6c7bb3834271","description":"Magn\u00e9sio","correct_answer":false},{"id":"01a2190a-af2f-7e18-86e8-885cb629eb73","description":"L\u00edtio","correct_answer":false}]},{"id":"01a2190a-af2f-7d00-8a21-240877a78983","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual escala \u00e9 usada para classificar a magnitude dos terremotos?","difficulty":1,"explanation":"Charles F. Richter e Beno Gutenberg introduziram a escala em 1935. Trata-se de uma escala logar\u00edtmica; portanto, cada aumento de um n\u00famero inteiro representa um aumento de dez vezes na amplitude da onda medida.","alternatives":[{"id":"01a2190a-af2f-7370-8fa3-2eb251d5a076","description":"Richter","correct_answer":true},{"id":"01a2190a-af2f-7f57-9421-f2ffac0d9ed5","description":"Beaufort","correct_answer":false},{"id":"01a2190a-af2f-7b17-af32-4739505bd83c","description":"Schweizer","correct_answer":false},{"id":"01a2190a-af2f-7a47-bb3e-410ed41ab353","description":"Hammer","correct_answer":false}]},{"id":"01a2190a-af2f-7cd4-ba1d-0a50a96128ed","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual organismo se ali